//! kvhttp: an in-memory HTTP/1.1 key-value server.
//!
//! Usage: `app <port>` — listens on `127.0.0.1:<port>` until killed.

mod service;
mod store;

use std::net::{Ipv4Addr, SocketAddr};
use std::process::ExitCode;
use std::sync::Arc;

use hyper::server::conn::http1;
use hyper::service::service_fn;
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;

use crate::store::Store;

fn parse_port() -> Result<u16, String> {
    let mut args = std::env::args().skip(1);
    match (args.next(), args.next()) {
        (Some(port), None) => port.parse().map_err(|_| format!("invalid port: {port}")),
        _ => Err("usage: app <port>".to_owned()),
    }
}

#[tokio::main]
async fn main() -> ExitCode {
    let port = match parse_port() {
        Ok(port) => port,
        Err(msg) => {
            eprintln!("{msg}");
            return ExitCode::from(2);
        }
    };

    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let listener = match TcpListener::bind(addr).await {
        Ok(listener) => listener,
        Err(err) => {
            eprintln!("failed to bind {addr}: {err}");
            return ExitCode::FAILURE;
        }
    };

    serve(listener, Arc::new(Store::new())).await
}

async fn serve(listener: TcpListener, store: Arc<Store>) -> ! {
    loop {
        let stream = match listener.accept().await {
            Ok((stream, _)) => stream,
            Err(err) => {
                // Typically transient (e.g. too many open files); keep serving.
                eprintln!("accept failed: {err}");
                tokio::task::yield_now().await;
                continue;
            }
        };
        let _ = stream.set_nodelay(true);

        let store = Arc::clone(&store);
        tokio::spawn(async move {
            let service = service_fn(move |req| service::handle(Arc::clone(&store), req));
            let result = http1::Builder::new()
                .serve_connection(TokioIo::new(stream), service)
                .await;
            if let Err(err) = result
                && !err.is_incomplete_message()
            {
                eprintln!("connection error: {err}");
            }
        });
    }
}

//! HTTP routing and request handling.

use std::convert::Infallible;
use std::sync::Arc;

use bytes::Bytes;
use http_body_util::{BodyExt, Full, LengthLimitError, Limited};
use hyper::body::Body;
use hyper::header::{self, HeaderValue};
use hyper::{Method, Request, Response, StatusCode};

use crate::store::Store;

/// Largest accepted value, in bytes.
pub const MAX_VALUE_BYTES: usize = 1 << 20;
const MAX_KEY_LEN: usize = 64;
const KV_PREFIX: &str = "/kv/";

const TEXT_PLAIN: HeaderValue = HeaderValue::from_static("text/plain; charset=utf-8");
const APPLICATION_JSON: HeaderValue = HeaderValue::from_static("application/json");

/// Returns whether `key` matches `[A-Za-z0-9_-]{1,64}`.
pub fn is_valid_key(key: &str) -> bool {
    (1..=MAX_KEY_LEN).contains(&key.len())
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

/// Handles a single request against `store`.
pub async fn handle<B>(
    store: Arc<Store>,
    req: Request<B>,
) -> Result<Response<Full<Bytes>>, Infallible>
where
    B: Body<Data = Bytes>,
    B::Error: std::error::Error + Send + Sync + 'static,
{
    let response = match req.uri().path() {
        "/health" => match *req.method() {
            Method::GET => text(StatusCode::OK, "ok"),
            _ => status(StatusCode::METHOD_NOT_ALLOWED),
        },
        "/kv" => match *req.method() {
            Method::GET => list_keys(&store),
            _ => status(StatusCode::METHOD_NOT_ALLOWED),
        },
        path => match path.strip_prefix(KV_PREFIX) {
            Some(key) if !is_valid_key(key) => status(StatusCode::BAD_REQUEST),
            Some(key) => {
                let key = key.to_owned();
                match *req.method() {
                    Method::GET => match store.get(&key) {
                        Some(value) => Response::new(Full::new(value)),
                        None => status(StatusCode::NOT_FOUND),
                    },
                    Method::PUT => put(&store, &key, req).await,
                    Method::DELETE if store.remove(&key) => status(StatusCode::NO_CONTENT),
                    Method::DELETE => status(StatusCode::NOT_FOUND),
                    _ => status(StatusCode::METHOD_NOT_ALLOWED),
                }
            }
            None => status(StatusCode::NOT_FOUND),
        },
    };
    Ok(response)
}

async fn put<B>(store: &Store, key: &str, req: Request<B>) -> Response<Full<Bytes>>
where
    B: Body<Data = Bytes>,
    B::Error: std::error::Error + Send + Sync + 'static,
{
    if let Some(declared) = req.headers().get(header::CONTENT_LENGTH) {
        match declared
            .to_str()
            .ok()
            .and_then(|s| s.trim().parse::<u64>().ok())
        {
            Some(len) if len > MAX_VALUE_BYTES as u64 => {
                return status(StatusCode::PAYLOAD_TOO_LARGE);
            }
            Some(_) => {}
            None => return status(StatusCode::BAD_REQUEST),
        }
    }

    let value = match Limited::new(req.into_body(), MAX_VALUE_BYTES)
        .collect()
        .await
    {
        Ok(collected) => collected.to_bytes(),
        Err(err) if err.is::<LengthLimitError>() => return status(StatusCode::PAYLOAD_TOO_LARGE),
        Err(_) => return status(StatusCode::BAD_REQUEST),
    };

    if store.put(key, value) {
        status(StatusCode::CREATED)
    } else {
        status(StatusCode::OK)
    }
}

fn list_keys(store: &Store) -> Response<Full<Bytes>> {
    // Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is needed.
    let keys = store.keys();
    let mut json = String::with_capacity(2 + keys.iter().map(|k| k.len() + 3).sum::<usize>());
    json.push('[');
    for (i, key) in keys.iter().enumerate() {
        if i > 0 {
            json.push(',');
        }
        json.push('"');
        json.push_str(key);
        json.push('"');
    }
    json.push(']');
    with_type(StatusCode::OK, APPLICATION_JSON, json)
}

fn status(code: StatusCode) -> Response<Full<Bytes>> {
    let mut response = Response::new(Full::default());
    *response.status_mut() = code;
    response
}

fn text(code: StatusCode, body: &'static str) -> Response<Full<Bytes>> {
    with_type(code, TEXT_PLAIN, body)
}

fn with_type(
    code: StatusCode,
    content_type: HeaderValue,
    body: impl Into<Bytes>,
) -> Response<Full<Bytes>> {
    let mut response = Response::new(Full::new(body.into()));
    *response.status_mut() = code;
    response
        .headers_mut()
        .insert(header::CONTENT_TYPE, content_type);
    response
}

#[cfg(test)]
mod tests {
    use super::*;

    async fn call(
        store: &Arc<Store>,
        method: &str,
        path: &str,
        body: &'static str,
    ) -> (StatusCode, Bytes) {
        let req = Request::builder()
            .method(method)
            .uri(path)
            .body(Full::new(Bytes::from_static(body.as_bytes())))
            .unwrap();
        let res = handle(Arc::clone(store), req).await.unwrap();
        let status = res.status();
        (status, res.into_body().collect().await.unwrap().to_bytes())
    }

    #[test]
    fn key_validation() {
        assert!(is_valid_key("a"));
        assert!(is_valid_key("A-z_09"));
        assert!(is_valid_key(&"k".repeat(64)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key(&"k".repeat(65)));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("bad.key"));
        assert!(!is_valid_key("é"));
        assert!(!is_valid_key("a%20b"));
    }

    #[tokio::test]
    async fn routes() {
        let store = Arc::new(Store::new());
        assert_eq!(
            call(&store, "GET", "/health", "").await,
            (StatusCode::OK, Bytes::from("ok"))
        );
        assert_eq!(
            call(&store, "POST", "/health", "").await.0,
            StatusCode::METHOD_NOT_ALLOWED
        );
        assert_eq!(
            call(&store, "GET", "/nope", "").await.0,
            StatusCode::NOT_FOUND
        );
        assert_eq!(
            call(&store, "GET", "/kv/", "").await.0,
            StatusCode::BAD_REQUEST
        );
        assert_eq!(
            call(&store, "GET", "/kv/a/b", "").await.0,
            StatusCode::BAD_REQUEST
        );
        assert_eq!(
            call(&store, "PUT", "/kv/b", "2").await.0,
            StatusCode::CREATED
        );
        assert_eq!(
            call(&store, "PUT", "/kv/a", "1").await.0,
            StatusCode::CREATED
        );
        assert_eq!(call(&store, "PUT", "/kv/a", "x").await.0, StatusCode::OK);
        assert_eq!(
            call(&store, "GET", "/kv/a", "").await,
            (StatusCode::OK, Bytes::from("x"))
        );
        assert_eq!(
            call(&store, "PATCH", "/kv/a", "").await.0,
            StatusCode::METHOD_NOT_ALLOWED
        );
        assert_eq!(
            call(&store, "POST", "/kv", "").await.0,
            StatusCode::METHOD_NOT_ALLOWED
        );
        assert_eq!(
            call(&store, "GET", "/kv", "").await,
            (StatusCode::OK, Bytes::from(r#"["a","b"]"#))
        );
        assert_eq!(
            call(&store, "DELETE", "/kv/a", "").await.0,
            StatusCode::NO_CONTENT
        );
        assert_eq!(
            call(&store, "DELETE", "/kv/a", "").await.0,
            StatusCode::NOT_FOUND
        );
        assert_eq!(
            call(&store, "GET", "/kv/a", "").await.0,
            StatusCode::NOT_FOUND
        );
    }
}

//! Thread-safe in-memory key-value store.

use std::collections::BTreeMap;
use std::sync::{PoisonError, RwLock};

use bytes::Bytes;

/// An ordered, concurrently accessible map from keys to byte values.
#[derive(Debug, Default)]
pub struct Store {
    entries: RwLock<BTreeMap<String, Bytes>>,
}

impl Store {
    pub fn new() -> Self {
        Self::default()
    }

    /// Returns the value stored under `key`, if any.
    pub fn get(&self, key: &str) -> Option<Bytes> {
        self.read().get(key).cloned()
    }

    /// Stores `value` under `key`, returning `true` if the key was new.
    pub fn put(&self, key: &str, value: Bytes) -> bool {
        self.write().insert(key.to_owned(), value).is_none()
    }

    /// Removes `key`, returning `true` if it was present.
    pub fn remove(&self, key: &str) -> bool {
        self.write().remove(key).is_some()
    }

    /// Returns every key in ascending order.
    pub fn keys(&self) -> Vec<String> {
        self.read().keys().cloned().collect()
    }

    // The map is never left in an inconsistent state by a panicking holder,
    // so a poisoned lock is safe to keep using.
    fn read(&self) -> std::sync::RwLockReadGuard<'_, BTreeMap<String, Bytes>> {
        self.entries.read().unwrap_or_else(PoisonError::into_inner)
    }

    fn write(&self) -> std::sync::RwLockWriteGuard<'_, BTreeMap<String, Bytes>> {
        self.entries.write().unwrap_or_else(PoisonError::into_inner)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn put_get_remove() {
        let store = Store::new();
        assert!(store.put("a", Bytes::from_static(b"1")));
        assert!(!store.put("a", Bytes::from_static(b"2")));
        assert_eq!(store.get("a").as_deref(), Some(&b"2"[..]));
        assert!(store.remove("a"));
        assert!(!store.remove("a"));
        assert_eq!(store.get("a"), None);
    }

    #[test]
    fn keys_are_sorted() {
        let store = Store::new();
        for key in ["b", "C", "a", "_", "-", "0"] {
            store.put(key, Bytes::new());
        }
        assert_eq!(store.keys(), ["-", "0", "C", "_", "a", "b"]);
    }
}
